"""Convert entity instances of IFC2X3 to AAS."""

import abc
import base64
import collections.abc
import copy
import re
from typing import (
    Any,
    Callable,
    Final,
    List,
    Mapping,
    MutableMapping,
    Optional,
    Sequence,
    Tuple,
    Union,
)
from typing_extensions import assert_never
import ifcopenshell
from aas_core3 import types as aas_types

_DROP_INS_IRI: Final[str] = (
    "https://aas-smt-from-ifc.aas-core-works.org/IFC2X3/drop-ins"
)

_SUBMODEL_TEMPLATES_IRI: Final[str] = (
    "https://aas-smt-from-ifc.aas-core-works.org/IFC2X3/submodel-templates"
)


def _model_reference(
    keys: Sequence[Tuple[aas_types.KeyTypes, str]],
) -> aas_types.Reference:
    return aas_types.Reference(
        type=aas_types.ReferenceTypes.MODEL_REFERENCE,
        keys=[aas_types.Key(type=key_type, value=value) for key_type, value in keys],
    )


_REFERENCE_TO_NUMBER_DROP_IN: Final[aas_types.Reference] = _model_reference(
    [
        (aas_types.KeyTypes.SUBMODEL, _DROP_INS_IRI),
        (aas_types.KeyTypes.PROPERTY, "Number"),
    ],
)

_REFERENCE_TO_LOGICAL_DROP_IN: Final[aas_types.Reference] = _model_reference(
    [
        (aas_types.KeyTypes.SUBMODEL, _DROP_INS_IRI),
        (aas_types.KeyTypes.PROPERTY, "Logical"),
    ],
)


def _bool_as_xs_bool_value(value: bool) -> str:
    """Convert a boolean to the corresponding literal of ``xs:boolean``."""
    return "true" if value else "false"


def _binary_to_property(value: Union[bytes, str]) -> aas_types.Property:
    """Translate the given value of a BINARY into a property element."""
    property_value: str
    if isinstance(value, str):
        if len(value) % 4 != 0 or _BASE64_RE.match(value) is None:
            value_snippet = value if len(value) < 128 else f"{value[:128]} [...]"
            raise ValueError(
                f"The binary value represented as a string {value_snippet} "
                f"is not a valid base64 encoding."
            )
        property_value = value
    elif isinstance(value, bytes):
        property_value = base64.b64encode(value).decode("utf-8")
    else:
        raise ValueError(f"Unexpected value: {value}")
    return aas_types.Property(
        value_type=aas_types.DataTypeDefXSD.BASE_64_BINARY, value=property_value
    )


def _logical_as_str(value: Optional[Union[bool, str]]) -> str:
    """Convert a logical value to the corresponding string."""
    if value is None:
        return "UNKNOWN"
    if isinstance(value, str):
        if value == "UNKNOWN":
            return "UNKNOWN"
        else:
            raise ValueError("Unexpected logical value: {value!r}")
    assert isinstance(value, bool)
    return "TRUE" if value else "FALSE"


def _number_to_collection(
    value: Union[int, float],
) -> aas_types.SubmodelElementCollection:
    """
    Convert the number value to a collection with ``value`` element.
    Neither the ID-short nor the semantic ID will be set.
    """
    if isinstance(value, int):
        value_type = aas_types.DataTypeDefXSD.LONG
    elif isinstance(value, float):
        value_type = aas_types.DataTypeDefXSD.DOUBLE
    else:
        raise ValueError(f"Unexpected number of type: {type(value)}")
    return aas_types.SubmodelElementCollection(
        semantic_id=copy.copy(_REFERENCE_TO_NUMBER_DROP_IN),
        value=[
            aas_types.Property(
                id_short="value", value_type=value_type, value=str(value)
            )
        ],
    )


_AAS_KEY_TYPES_BY_CLASS = {
    aas_types.AnnotatedRelationshipElement: aas_types.KeyTypes.ANNOTATED_RELATIONSHIP_ELEMENT,
    aas_types.AssetAdministrationShell: aas_types.KeyTypes.ASSET_ADMINISTRATION_SHELL,
    aas_types.BasicEventElement: aas_types.KeyTypes.BASIC_EVENT_ELEMENT,
    aas_types.Blob: aas_types.KeyTypes.BLOB,
    aas_types.Capability: aas_types.KeyTypes.CAPABILITY,
    aas_types.ConceptDescription: aas_types.KeyTypes.CONCEPT_DESCRIPTION,
    aas_types.DataElement: aas_types.KeyTypes.DATA_ELEMENT,
    aas_types.Entity: aas_types.KeyTypes.ENTITY,
    aas_types.EventElement: aas_types.KeyTypes.EVENT_ELEMENT,
    aas_types.File: aas_types.KeyTypes.FILE,
    aas_types.MultiLanguageProperty: aas_types.KeyTypes.MULTI_LANGUAGE_PROPERTY,
    aas_types.Operation: aas_types.KeyTypes.OPERATION,
    aas_types.Property: aas_types.KeyTypes.PROPERTY,
    aas_types.Range: aas_types.KeyTypes.RANGE,
    aas_types.Referable: aas_types.KeyTypes.REFERABLE,
    aas_types.ReferenceElement: aas_types.KeyTypes.REFERENCE_ELEMENT,
    aas_types.RelationshipElement: aas_types.KeyTypes.RELATIONSHIP_ELEMENT,
    aas_types.Submodel: aas_types.KeyTypes.SUBMODEL,
    aas_types.SubmodelElement: aas_types.KeyTypes.SUBMODEL_ELEMENT,
    aas_types.SubmodelElementCollection: aas_types.KeyTypes.SUBMODEL_ELEMENT_COLLECTION,
    aas_types.SubmodelElementList: aas_types.KeyTypes.SUBMODEL_ELEMENT_LIST,
}


class _StructuralType(abc.ABC):
    """Match the type of a value at runtime and translate it to an element."""

    @abc.abstractmethod
    def match(self, value: Any) -> bool:
        """Check whether the ``value`` conforms to the type."""
        raise NotImplementedError()

    @abc.abstractmethod
    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        """
        Translate the ``value`` to the corresponding element.

        The function ``identify`` determines the global identifiers of entities mapped
        to submodels.
        """
        raise NotImplementedError()


class _Boolean(_StructuralType):
    def match(self, value: Any) -> bool:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        return isinstance(value, bool)

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue

        assert isinstance(value, bool)
        return aas_types.Property(
            value_type=aas_types.DataTypeDefXSD.BOOLEAN,
            value=_bool_as_xs_bool_value(value),
        )

    def __str__(self) -> str:
        return "BOOLEAN"


class _Integer(_StructuralType):
    def match(self, value: Any) -> bool:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue

        return isinstance(value, int)

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue

        assert isinstance(value, int)
        return aas_types.Property(
            value_type=aas_types.DataTypeDefXSD.LONG, value=str(value)
        )

    def __str__(self) -> str:
        return "INTEGER"


class _Real(_StructuralType):
    def match(self, value: Any) -> bool:
        if hasattr(value, "wrappedValue"):

            value = value.wrappedValue
        return isinstance(value, (int, float))

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue

        assert isinstance(value, (int, float))
        return aas_types.Property(
            value_type=aas_types.DataTypeDefXSD.DOUBLE, value=str(value)
        )

    def __str__(self) -> str:
        return "REAL"


class _Number(_StructuralType):
    def match(self, value: Any) -> bool:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue

        return isinstance(value, (int, float))

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        assert isinstance(value, (int, float))
        return _number_to_collection(value)

    def __str__(self) -> str:
        return "NUMBER"


class _Logical(_StructuralType):
    def match(self, value: Any) -> bool:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        return (
            value is None
            or isinstance(value, bool)
            or (isinstance(value, str) and value == "UNKNOWN")
        )

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        assert (
            value is None
            or isinstance(value, bool)
            or (isinstance(value, str) and value == "UNKNOWN")
        )
        return aas_types.Property(
            semantic_id=_REFERENCE_TO_LOGICAL_DROP_IN,
            value_type=aas_types.DataTypeDefXSD.STRING,
            value=_logical_as_str(value),
        )

    def __str__(self) -> str:
        return "LOGICAL"


_BASE64_RE = re.compile(r"^[A-Za-z0-9+/]+={{0,2}}$")


class _Binary(_StructuralType):
    def __init__(
        self, min_length: Optional[int] = None, max_length: Optional[int] = None
    ) -> None:
        self.min_length = min_length
        self.max_length = max_length

    def match(self, value: Any) -> bool:
        # NOTE (mristin):
        # The IFC Open Shell often does not distinguish between base64-encoded
        # strings and bytes, so we have to handle both here.
        # This might lead to confusion -- if there is an explicit STRING holding
        # a base64-encoded value, we can not tell it apart from BINARY.
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        if isinstance(value, str):
            if len(value) % 4 != 0:
                return False
            if _BASE64_RE.match(value) is None:
                return False
            length = 3 * (len(value) // 4) - value.count("=")
            if self.min_length is not None and length < self.min_length:
                return False
            if self.max_length is not None and length > self.max_length:
                return False
            return True
        elif isinstance(value, bytes):
            if self.min_length is not None and len(value) < self.min_length:
                return False
            if self.max_length is not None and len(value) > self.max_length:
                return False
            return True
        else:
            raise ValueError("Expected either str or bytes, but got: {value}")

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        assert isinstance(value, (str, bytes))
        return _binary_to_property(value)

    def __str__(self) -> str:
        if self.min_length is None and self.max_length is None:
            return "BINARY"
        if self.min_length == self.max_length:
            return f"BINARY ({self.max_length}) FIXED"
        if self.min_length is None and self.max_length is not None:
            return f"BINARY ({self.max_length})"
        return f"BINARY ({self.min_length}, ?)"


class _String(_StructuralType):
    def __init__(
        self,
        min_length: Optional[int] = None,
        max_length: Optional[int] = None,
        choice: Optional[List[str]] = None,
    ) -> None:
        self.min_length = min_length
        self.max_length = max_length
        self.choice_set = set(choice) if choice is not None else None

    def match(self, value: Any) -> bool:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue

        if not isinstance(value, str):
            return False

        if self.min_length is not None and len(value) < self.min_length:
            return False

        if self.max_length is not None and len(value) > self.max_length:
            return False

        if self.choice_set is not None and value not in self.choice_set:
            return False

        return True

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        if hasattr(value, "wrappedValue"):
            value = value.wrappedValue
        return aas_types.Property(
            value_type=aas_types.DataTypeDefXSD.STRING, value=value
        )

    def __str__(self) -> str:
        if self.min_length is None and self.max_length is None:
            return "STRING"
        if self.min_length == self.max_length:
            return f"STRING ({self.max_length}) FIXED"
        if self.min_length is None and self.max_length is not None:
            return f"STRING ({self.max_length})"
        return f"STRING ({self.min_length}, ?)"


def _type_value_list_element_from_of_structural_type(
    of: "_StructuralTypeUnion",
) -> aas_types.AASSubmodelElements:
    while isinstance(of, _DeclaredType):
        of = of.structural_type
    assert not isinstance(of, _DeclaredType)
    if isinstance(of, (_Boolean, _Logical, _Integer, _Real, _Binary, _String)):
        type_value_list_element = aas_types.AASSubmodelElements.PROPERTY
    elif isinstance(of, _Number):
        type_value_list_element = (
            aas_types.AASSubmodelElements.SUBMODEL_ELEMENT_COLLECTION
        )
    elif isinstance(of, (_Array, _Bag, _List, _Set)):
        type_value_list_element = aas_types.AASSubmodelElements.SUBMODEL_ELEMENT_LIST
    elif isinstance(of, _Select):
        type_value_list_element = (
            aas_types.AASSubmodelElements.SUBMODEL_ELEMENT_COLLECTION
        )
    elif isinstance(of, _Entity):
        if of.identifier in _TO_SUBMODEL_MAP:
            type_value_list_element = aas_types.AASSubmodelElements.REFERENCE_ELEMENT
        elif of.identifier in _TO_SUBMODEL_ELEMENT_COLLECTION_MAP:
            type_value_list_element = (
                aas_types.AASSubmodelElements.SUBMODEL_ELEMENT_COLLECTION
            )
        else:
            raise ValueError(f"Unexpected instance of entity {of.identifier}")
    elif isinstance(of, _Enumeration):
        type_value_list_element = aas_types.AASSubmodelElements.PROPERTY
    else:
        assert_never(of)
    return type_value_list_element


def _value_type_list_element_from_of_structural_type(
    of: "_StructuralTypeUnion",
) -> Optional[aas_types.DataTypeDefXSD]:
    while isinstance(of, _DeclaredType):
        of = of.structural_type
    assert not isinstance(of, _DeclaredType)
    if isinstance(of, _Boolean):
        return aas_types.DataTypeDefXSD.BOOLEAN
    elif isinstance(of, _Logical):
        return aas_types.DataTypeDefXSD.STRING
    elif isinstance(of, _Integer):
        return aas_types.DataTypeDefXSD.LONG
    elif isinstance(of, _Real):
        return aas_types.DataTypeDefXSD.DOUBLE
    elif isinstance(of, _Binary):
        return aas_types.DataTypeDefXSD.BASE_64_BINARY
    elif isinstance(of, _String):
        return aas_types.DataTypeDefXSD.STRING
    elif isinstance(of, _Enumeration):
        return aas_types.DataTypeDefXSD.STRING
    else:
        return None


class _Array(_StructuralType):
    def __init__(
        self,
        of: "_StructuralTypeUnion",
        min_length: Optional[int] = None,
        max_length: Optional[int] = None,
        optional: bool = False,
    ) -> None:
        self.of = of
        self.min_length = min_length
        self.max_length = max_length
        self.optional = optional

    def match(self, value: Any) -> bool:
        if not isinstance(value, collections.abc.Sequence):
            return False

        if self.min_length is not None and len(value) < self.min_length:
            return False

        if self.max_length is not None and len(value) > self.max_length:
            return False

        if self.optional:
            if not all(item is None or self.of.match(item) for item in value):

                return False

        else:
            if not all(self.of.match(item) for item in value):
                return False

        return True

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        assert isinstance(value, collections.abc.Sequence)
        elements: Optional[List[aas_types.SubmodelElement]]
        if self.optional:
            elements = []
            for item in value:
                value_element = self.of.translate(item, identify)
                value_element.id_short = "value"
                elements.append(
                    aas_types.SubmodelElementCollection(value=[value_element])
                )
        else:
            elements = [self.of.translate(item, identify) for item in value]
        type_value_list_element: aas_types.AASSubmodelElements
        value_type_list_element: Optional[aas_types.DataTypeDefXSD] = None
        if self.optional:
            type_value_list_element = (
                aas_types.AASSubmodelElements.SUBMODEL_ELEMENT_COLLECTION
            )
        else:
            type_value_list_element = _type_value_list_element_from_of_structural_type(
                self.of
            )
            value_type_list_element = _value_type_list_element_from_of_structural_type(
                self.of
            )
        return aas_types.SubmodelElementList(
            value=elements if len(elements) > 0 else None,
            type_value_list_element=type_value_list_element,
            value_type_list_element=value_type_list_element,
            order_relevant=True,
        )

    def __str__(self) -> str:
        optional = " OPTIONAL " if self.optional else ""
        if self.min_length is None and self.max_length is None:
            return f"ARRAY {optional}OF {self.of}"
        min_length = str(self.min_length) if self.min_length is not None else "?"
        max_length = str(self.max_length) if self.max_length is not None else "?"
        return f"ARRAY [{min_length}:{max_length}] {optional}OF {self.of}"


class _Bag(_StructuralType):
    def __init__(
        self,
        of: "_StructuralTypeUnion",
        min_length: Optional[int] = None,
        max_length: Optional[int] = None,
    ) -> None:
        self.of = of
        self.min_length = min_length
        self.max_length = max_length

    def match(self, value: Any) -> bool:
        if not isinstance(value, collections.abc.Sequence):
            return False

        if self.min_length is not None and len(value) < self.min_length:
            return False

        if self.max_length is not None and len(value) > self.max_length:
            return False

        if not all(self.of.match(item) for item in value):
            return False

        return True

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        assert isinstance(value, collections.abc.Sequence)
        elements: Optional[List[aas_types.SubmodelElement]]
        elements = [self.of.translate(item, identify) for item in value]
        return aas_types.SubmodelElementList(
            value=elements if len(elements) > 0 else None,
            type_value_list_element=(
                _type_value_list_element_from_of_structural_type(self.of)
            ),
            value_type_list_element=(
                _value_type_list_element_from_of_structural_type(self.of)
            ),
            order_relevant=False,
        )

    def __str__(self) -> str:
        if self.min_length is None and self.max_length is None:
            return f"BAG OF {self.of}"
        min_length = str(self.min_length) if self.min_length is not None else "?"
        max_length = str(self.max_length) if self.max_length is not None else "?"
        return f"BAG [{min_length}:{max_length}] OF {self.of}"


