def _flatten_select_choice(
    choice: Sequence[Union["_DeclaredType", "_Entity", "_Enumeration"]],
) -> List[Union["_DeclaredType", "_Entity", "_Enumeration"]]:
    result = []  # type: List[Union["_DeclaredType", "_Entity", "_Enumeration"]]
    for selected_type in choice:
        resolved_type = selected_type  # type: "_StructuralTypeUnion"
        while isinstance(resolved_type, _DeclaredType):
            resolved_type = resolved_type.structural_type
        assert not isinstance(resolved_type, _DeclaredType)
        if not isinstance(resolved_type, _Select):
            result.append(selected_type)
            continue
        result.extend(_flatten_select_choice(resolved_type.choice))
    return result


class _Select(_StructuralType):
    def __init__(
        self, choice: Sequence[Union["_DeclaredType", "_Entity", "_Enumeration"]]
    ) -> None:
        # NOTE (mristin):
        # We flatten here the selection to account for union of unions.
        # The selections are just another name for union types (a.k.a. sum types).
        self.choice = _flatten_select_choice(choice)

    def match(self, value: Any) -> bool:
        return any(selected_type.match(value) for selected_type in self.choice)

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        for selected_type in self.choice:
            if selected_type.match(value):
                element = selected_type.translate(value, identify)
                element.id_short = "value"
                element.semantic_id = _model_reference(
                    [
                        (aas_types.KeyTypes.SUBMODEL, _DROP_INS_IRI),
                        (
                            _AAS_KEY_TYPES_BY_CLASS[element.__class__],
                            selected_type.identifier,
                        ),
                    ]
                )
                return aas_types.SubmodelElementCollection(value=[element])
        raise ValueError(f"None of the types in the select choice matched {value}")

    def __str__(self) -> str:
        entries_joined = ",\n".join(str(selected_type) for selected_type in self.choice)
        return f"SELECT({entries_joined})"


class _Entity(_StructuralType):
    def __init__(self, identifier: str) -> None:
        self.identifier = identifier

    def match(self, value: Any) -> bool:
        return isinstance(value, ifcopenshell.entity_instance) and value.is_a(
            self.identifier
        )

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        assert isinstance(value, ifcopenshell.entity_instance) and value.is_a(
            self.identifier
        )
        entity_name = value.is_a()

        if entity_name in _TO_SUBMODEL_MAP:
            return aas_types.ReferenceElement(
                value=_model_reference([(aas_types.KeyTypes.SUBMODEL, identify(value))])
            )

        elif entity_name in _TO_SUBMODEL_ELEMENT_COLLECTION_MAP:
            return must_translate_to_submodel_element_collection(
                instance=value, identify=identify
            )

        else:
            raise ValueError(
                f"We do not know how to map an instance of the entity {entity_name} "
                f"to its AAS correspondent."
            )

    def __str__(self) -> str:
        return self.identifier


class _Enumeration(_StructuralType):
    def __init__(self, identifier: str, choice: Sequence[str]) -> None:
        self.identifier = identifier
        self.choice_set = set(choice)

    def match(self, value: Any) -> bool:
        return isinstance(value, str) and value in self.choice_set

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        assert isinstance(value, str)

        return aas_types.Property(
            semantic_id=aas_types.Reference(
                type=aas_types.ReferenceTypes.MODEL_REFERENCE,
                keys=[
                    aas_types.Key(
                        type=aas_types.KeyTypes.SUBMODEL, value=_DROP_INS_IRI
                    ),
                    aas_types.Key(
                        type=aas_types.KeyTypes.PROPERTY, value=self.identifier
                    ),
                ],
            ),
            value_type=aas_types.DataTypeDefXSD.STRING,
            value=value,
        )

    def __str__(self) -> str:
        return self.identifier


class _DeclaredType(_StructuralType):
    def __init__(
        self, identifier: str, structural_type: "_StructuralTypeUnion"
    ) -> None:
        self.identifier = identifier
        self.structural_type = structural_type

    def match(self, value: Any) -> bool:
        return self.structural_type.match(value)

    def translate(
        self, value: Any, identify: Callable[[ifcopenshell.entity_instance], str]
    ) -> aas_types.SubmodelElement:
        return self.structural_type.translate(value, identify)

    def __str__(self) -> str:
        return self.identifier


_StructuralTypeUnion = Union[
    _Boolean,
    _Logical,
    _Integer,
    _Real,
    _Number,
    _Binary,
    _String,
    _Array,
    _Bag,
    _List,
    _Set,
    _Select,
    _Entity,
    _Enumeration,
    _DeclaredType,
]


class _Attribute:
    def __init__(
        self,
        name: str,
        structural_type: _StructuralTypeUnion,
        optional: bool = False,
    ) -> None:
        self.name = name
        self.structural_type = structural_type
        self.optional = optional


class _EntityDeclaration:
    def __init__(self, identifier: str, attributes: List[_Attribute]) -> None:
        self.identifier = identifier
        self.attributes = attributes


class Logger:
    """Log errors instead of raising exceptions on schema violations."""

    def __init__(self) -> None:
        self.messages = []  # type: List[str]

    def error(self, message: str) -> None:
        """Log the error message."""
        self.messages.append(message)


def _to_elements_by_declaration(
    instance: ifcopenshell.entity_instance,
    identify: Callable[[ifcopenshell.entity_instance], str],
    declaration: _EntityDeclaration,
    logger: Optional[Logger],
) -> List[aas_types.SubmodelElement]:
    """Translate the given instance into its elements following its declaration."""
    elements = []  # type: List[aas_types.SubmodelElement]
    for attribute in declaration.attributes:
        if not hasattr(instance, attribute.name):
            message = (
                f"Attribute {attribute.name} is missing "
                f"in an instance {instance} presumed "
                f"to be of entity {declaration.identifier}."
            )

            if logger is not None:
                logger.error(message)
                continue

            raise ValueError(message)

        value = getattr(instance, attribute.name)
        if attribute.optional and value is None:
            continue

        if not attribute.structural_type.match(value):
            message = (
                f"Attribute {attribute.name} with value {value} "
                f"of instance {instance} does not match "
                f"the expected structural type {attribute.structural_type}; skipping"
            )

            if logger is not None:
                logger.error(message)
                continue

            raise ValueError(message)

        element = attribute.structural_type.translate(value, identify)
        element.id_short = attribute.name
        elements.append(element)
    return elements


def _to_submodel_by_declaration(
    instance: ifcopenshell.entity_instance,
    identify: Callable[[ifcopenshell.entity_instance], str],
    declaration: _EntityDeclaration,
    logger: Optional[Logger],
) -> aas_types.Submodel:
    """
    Translate an ``instance`` to a submodel following the ``declaration``.

    The function ``identify`` determines the global identifiers of entities mapped
    to submodels.

    If ``logger`` is supplied, the violations of the schema will be written to it,
    and the translation will continue. Otherwise, a ``ValueError`` will be immediately
    raised.
    """
    elements = _to_elements_by_declaration(
        instance=instance, identify=identify, declaration=declaration, logger=logger
    )
    return aas_types.Submodel(
        id=identify(instance),
        semantic_id=_model_reference(
            [
                (
                    aas_types.KeyTypes.SUBMODEL,
                    f"{_SUBMODEL_TEMPLATES_IRI}/{declaration.identifier}",
                ),
            ]
        ),
        submodel_elements=elements if len(elements) > 0 else None,
    )


def _to_submodel_element_collection_by_declaration(
    instance: ifcopenshell.entity_instance,
    identify: Callable[[ifcopenshell.entity_instance], str],
    declaration: _EntityDeclaration,
    logger: Optional[Logger],
) -> aas_types.SubmodelElementCollection:
    """
    Convert an ``instance`` to a submodel element collection by the ``declaration``.

    The function ``identify`` determines the global identifiers of entities mapped
    to submodels.

    If ``logger`` is supplied, the violations of the schema will be written to it,
    and the translation will continue. Otherwise, a ``ValueError`` will be immediately
    raised.
    """
    elements = _to_elements_by_declaration(
        instance=instance, identify=identify, declaration=declaration, logger=logger
    )
    return aas_types.SubmodelElementCollection(
        semantic_id=_model_reference(
            [
                (aas_types.KeyTypes.SUBMODEL, _DROP_INS_IRI),
                (
                    aas_types.KeyTypes.SUBMODEL_ELEMENT_COLLECTION,
                    declaration.identifier,
                ),
            ]
        ),
        value=elements if len(elements) > 0 else None,
    )


